const fs = require('fs');
const path = require('path');
const { getOrCreateKeyPair, signEntitlementToken } = require('../license_server/cryptoUtils');

const keyData = getOrCreateKeyPair();

// Create a test token as generated by License Server
const samplePayload = {
  exp: Math.floor(Date.now() / 1e3) + 30 * 86400,
  plan: 'gold',
  planName: 'Gold VIP (1 Năm)',
  planTier: 'ultra',
  status: 'active',
  features: { imageGeneration: true, videoGeneration: true, tts: true, chat: true, workflows: true, premiumTemplates: true, providerConfig: true, updates: true },
  limits: { unlimited: true, maxConcurrency: 50 },
  machineCode: 'test-machine-hwid-12345',
  sub: 'customer@gmail.com',
  licenseId: 'LIC-TEST',
  activationId: 'ACT-TEST'
};

const tokenStr = signEntitlementToken(samplePayload, keyData.privateKey, keyData.keyId);
console.log('[*] Generated sample token with server key:', tokenStr.slice(0, 50) + '...');

const targets = [
  path.join(__dirname, '../app/out/main/index.js'),
  path.join(__dirname, '../extracted_original/out/main/index.js'),
  path.join(__dirname, '../dist/AI_VIDEO_LIBRARY_Customer_Edition/resources/app/out/main/index.js')
];

for (const target of targets) {
  if (!fs.existsSync(target)) continue;
  console.log('[*] Testing verifier in:', target);
  const code = fs.readFileSync(target, 'utf8');

  // Find class iw (verifier)
  const start = code.indexOf('class iw{');
  const end = code.indexOf('class hw{');
  const snippet = code.substring(start, end);

  const testFn = new Function('require', 'Buffer', 'keyData', 'tokenStr', `
    const crypto = require('crypto');
    function ed(e) { return crypto.createPublicKey(e); }
    function td(a, b, c, d) { return crypto.verify(null, b, c, d); }
    const aw = "aiforge-license-server";
    const sw = "aiforge-studio";
    ${snippet}
    const verifier = new iw({ [keyData.keyId]: keyData.publicKey });
    return verifier.verifyEntitlement(tokenStr);
  `);

  const result = testFn(require, Buffer, keyData, tokenStr);
  console.log(`  ✓ Verified successfully! Plan: ${result.planName}, Machine: ${result.machineCode}`);
}

console.log('\n🌟 ALL MAIN BUNDLES VERIFY TOKENS 100% ERROR-FREE! 🌟');
